from datetime import datetime
from flask import Flask

app = Flask(__name__)

@app.template_filter('format_datetime')
def format_datetime_filter(value: datetime, fmt: str = '%Y-%m-%d %H:%M') -> str:
    if not value:
        return ''
    return value.strftime(fmt)
