from flask import Flask, session

app = Flask(__name__)
app.secret_key = 'test-secret'

@app.route('/set')
def set_val():
    session['user'] = 'alice'
    return 'ok'

@app.route('/get')
def get_val():
    return session.get('user', 'none')

def test_session_persistence():
    client = app.test_client()
    client.get('/set')
    res = client.get('/get')
    assert res.data.decode('utf-8') == 'alice'
